#[madsim::test]
async fn vote_survives_restart() {
    let runtime = Handle::current();
    let peers: Vec<SocketAddr> = (1..=3).map(|n| SocketAddr::from(([10, 9, 0, n], 1))).collect();
    let addr = peers[0];
    let host = create_node(&runtime, addr);
